from lib import *
S = SS('g16')
steps = [
    step("同一份代码,只改 go.mod 里的 go 指令。go 1.21:三个闭包捕获 for 的 i,循环结束后依次调用得到 3 3 3;取 &i 存进切片,三个指针相同,解引用得到 3 3 3;for range 里起 goroutine 引用 v,收集到 [30 30 30]。go 1.22 与 go 1.27:0 1 2;三个指针不同,解引用 0 1 2;收集到 [10 20 30]。", t=tl(S(1)), done=lidx(S(1), 'go.mod 写 go 1.22', 'go.mod 写 go 1.27'), mark=lidx(S(1), 'go.mod 写 go 1.21', '3 3 3', '[30 30 30]'), kv=KV([['go 1.21(旧语义)', '闭包 3 3 3;三个 &i 相同;goroutine 收集到 [30 30 30]'], ['go 1.22 与 1.27(新语义)', '闭包 0 1 2;三个 &i 不同;goroutine 收集到 [10 20 30]']], ['go 1.21(旧语义)'])),
    step("语义由编译单元的 Go 版本决定。go.mod 写 go 1.27,但文件 old.go 带 //go:build go1.21:新语义文件 collectNew 得到 [0 1 2],旧语义文件 collectOld 得到 [3 3 3]。", t=tl(S(2)), done=lidx(S(2), '新语义文件'), mark=lidx(S(2), '旧语义文件'), kv=KV([['go.mod 的 go 指令', '决定默认语义'], ['文件的 //go:build go1.21', '该文件按旧语义编译:[3 3 3]'], ['没有约束的文件', '新语义:[0 1 2]']], ['文件的 //go:build go1.21'])),
    step("编译器能列出受影响的循环:-gcflags=-d=loopvar=2 对示例打印:11:6 loop variable i now per-iteration, stack-allocated(闭包只留在局部);19:6 loop variable i now per-iteration, heap-allocated(取了 &i 存进切片,逃逸);25:9 loop variable v now per-iteration, stack-allocated。", t=tl(S(3)), done=lidx(S(3), 'stack-allocated'), mark=lidx(S(3), 'heap-allocated'), kv=KV([['11:6 i', 'per-iteration, stack-allocated'], ['19:6 i(取 &i 存进切片)', 'per-iteration, heap-allocated'], ['25:9 v', 'per-iteration, stack-allocated']], ['19:6 i(取 &i 存进切片)'])),
    step("代价:100 次迭代、闭包被保存下来,go 1.21 语义是 102 次分配,go 1.27 语义是 101 次(差 1 次,我推测是旧语义里共享的那个 i 被放到了堆上,没有逐项验证);只在循环里立刻调用的闭包两种语义都是 0 次分配。新语义在这个例子里没有多出每次迭代一次的分配。", t=tl(S(4)), done=lidx(S(4), 'go 1.21', 'go 1.27'), mark=lidx(S(4), '101 次分配'), b=bars([['go 1.21 语义:分配次数', 102, '102'], ['go 1.27 语义:分配次数', 101, '101']], 102, done=[1], mark=[0]), kv=KV([['go 1.21', '102 次'], ['go 1.27', '101 次'], ['立刻调用的闭包', '两种语义都是 0 次']], ['go 1.27'])),
    step("闭包捕获的是变量,不是值:counter 返回的两个闭包共享同一个 n,inc() 三次后 get() = 3,编译器说 moved to heap: n;x := 1、f 返回 x、之后 x = 99:f() = 99;把 y 作为参数传给立即调用的函数(参数是拷贝)后改 y = 99:g() = 1。", t=tl(S(5)), done=lidx(S(5), '共享同一个 n', 'moved to heap: n'), mark=lidx(S(5), 'f() = 99', 'g() = 1'), kv=KV([['两个闭包共享 n', 'inc() 三次后 get() = 3'], ['闭包创建后改 x', 'f() = 99(看得到)'], ['把 y 作为参数传入(拷贝)', 'g() = 1(看不到)'], ['编译器', 'moved to heap: n']], ['闭包创建后改 x'])),
]
A = mkartg('g16', 16, 'Go,闭包,for 循环变量,go.mod,loopvar,真实验证,动画演示',
    '用 Go 1.27.1 实测 Go 1.22 的循环变量语义变化:只改 go.mod 的 go 指令,同一份代码的闭包、&i 与 goroutine 的结果从 3 3 3 / [30 30 30] 变成 0 1 2 / [10 20 30];//go:build go1.21 可以让单个文件按旧语义编译;-d=loopvar=2 列出受影响的循环;闭包被保存的 100 次迭代在两种语义下分配次数几乎相同(102 与 101);闭包捕获的是变量。',
    'Go 1.22 把 for 循环的变量从“整个循环一份”改成了“每次迭代一份”,修掉了一个著名的陷阱。这篇不靠文档,用同一份代码在不同的 go.mod 版本下构建运行,对比结果;再看单文件覆盖、编译器的诊断,以及性能代价到底有多大。',
    [('3 3 3 → 0 1 2', '同一份代码,go.mod 从 go 1.21 改成 go 1.22 之后三个闭包的返回值'), ('go 指令', '循环变量语义由 go.mod(与文件级 //go:build)里的 Go 版本决定,而不是工具链版本'), ('102 vs 101', '闭包被保存的 100 次迭代,两种语义的分配次数')],
    [('旧语义与新语义', '<p>旧语义下整个循环只有一个 <code>i</code>,闭包与 <code>&i</code> 拿到的都是它,循环结束时它是 3;新语义下每次迭代有自己的 <code>i</code>,闭包得到各自的值。<code>for range</code> 的 <code>v</code> 同理——这就是 goroutine 引用循环变量时旧版本里常见的 bug。工具链是 Go 1.27.1,但 <code>go.mod</code> 写 <code>go 1.21</code> 时它仍按旧语义编译,所以升级工具链不会悄悄改变旧模块的行为。</p>'),
     ('文件级覆盖', '<p>语言版本也可以用文件头部的 <code>//go:build go1.21</code> 约束到单个文件。这个文件会按旧语义编译,可用来逐个文件地迁移或定位问题。需要注意的是,版本约束带来的这种效果是实测观察,本文没有去读工具链里处理它的代码。</p>'),
     ('让编译器告诉你', '<p><code>-gcflags=-d=loopvar=2</code> 打印每个“语义已改变”的循环,并说明那个变量最终放在栈上还是堆上。升级到 1.22 之前后对一个大项目跑一遍,能找到真正会被影响的位置。</p>'),
     ('代价', '<p>人们担心“每次迭代一个新变量”会多出分配。实测的闭包保存例子里没有多出:新语义是 101 次,旧语义反而是 102 次。这是这个例子的结果:闭包捕获的变量如果在被捕获后不再修改,闭包可以直接保存它的值,我没有读编译器里这条优化的实现,所以只能说“实测没有额外分配”。</p>'),
     ('捕获的是变量', '<p>不论哪个版本,闭包捕获的是变量本身而不是值:两个闭包共享 <code>n</code>,创建闭包之后修改的 <code>x</code> 也能被看到(<code>n</code> 因此被编译器放到堆上)。想要拷贝就把它作为参数传进去,或者在循环体里写 <code>v := v</code>(旧版本里的惯用法,本文没有运行)。</p>')],
    steps,
    [ENV_G + '。每个版本的对比都是同一份源码,只改 go.mod 的 go 指令(1.21 / 1.22 / 1.27)后构建运行;分配次数来自 testing.AllocsPerRun(100 次);编译器诊断来自 -gcflags=-d=loopvar=2 与 -m 的原样输出',
     '没有验证:GOEXPERIMENT 或更老的工具链上的行为、go.mod 里 toolchain 行的影响、闭包按值捕获优化的条件、for 循环里 defer 引用循环变量的情形、v := v 惯用法在新旧版本里的行为'],
    '闭包与循环变量')
